import json

def process_t1693():
    path = "/home/user/workspace/13511660557912876654/buddhist-ontology/data/baihua-tasks/t1693.skel.json"
    out = "/home/user/workspace/13511660557912876654/buddhist-ontology/data/modern-translation/t1693.json"
    with open(path, 'r', encoding='utf-8') as f:
        data = json.load(f)
    trans_list = data["translations"]
    moderns = [
        "【经题总序】【义解】《人本欲生经》，是阐明十二因缘而成就四谛的经典。「本」，就是痴，也就是欲爱；「生」，就是生死。经题简略举出十二因缘中的三者作为根本要旨。人在生死之中，没有不浪迹滞留在三世、飘萦在九止（识的九种住处）、缠绵于八种束缚之中的。十二因缘对应九止，第一处就是人，也包括天。四谛所鉴照的，就是鉴照这九止；八解脱所正的，就是正于八邪。邪正端正则无处不恬适，止观鉴照则无处不愉悦；无处不愉悦所以能洞照傍通，无处不恬适所以能神变应会；神变应会则不疾而速，洞照傍通则不言而化；不言而化所以没有被遗弃的人，不疾而速所以没有被遗漏的物。物不被遗漏、人不被遗弃，这是禅智所成就的。所以经说「道从禅智得近泥洹」，哪里是虚言呢！实在是近道归真的要道啊。这部经疑似安世高翻译为晋代汉语的。",
        "【注解缘起】【义解】经文古奥言简意赅，义理玄妙理致婉曲，能窥见其幽堂之美、庭阙之富的人或许很少。我每次披览其文，欲罢不能，所乐于玩味的是三观的妙义，所沉思存念的是想灭的言辞。冒昧利用余暇为它作撮要注解，其中义理相同而文辞有别的地方就不再加以训释了。后汉安息三藏安世高译。我是这样听闻的：一时佛在拘类国，游化拘类国的法治之处。这是阿难记录所闻圣教的地方。法治处，就是王城。当时贤者阿难独自在闲静处安居，倾心思惟，生起这样的念头：这意的生起真是稀有，这意是微妙的根本，生死也是微妙的，其中也微妙，只是分明易现。现当作见。这是意微妙本，是句倒装。于是贤者阿难，夜尽之后起来前往佛处。到了之后，为佛足下顶礼完毕，在一处坐下。坐定之后，贤者阿难对佛说：刚才我独自在闲静处倾心思惟，生起这样的念头：这意生起真是稀有，这意是微妙的根本。",
        "【痴为本义】【义解】本，就是痴。解脱痴，是四谛所照了的。生死亦微妙。生死是最末端的果，微明的谛理达于末端。中微妙。中，就是本末之间。九种识止处，用谛理照烛它，也是非常微妙的。但为分明易现。现，应当作「见」。是说用四谛观照十一因缘了了分明，不难知晓。佛告诉阿难：不要说这是分明易知易见的，这甚深微妙。阿难！从有本，才有生死。阿难！从本因缘而有生死，对于这个道理不知不见、不解不受，就令世间如同织机上的线蹑梭往来流转。这里说从痴而有这生死，极其深邃微妙，怎么能说容易见到呢？自从有痴以来经历尘数劫数累受身形，悠悠泛泛的比丘有不了谛理，反观如实之道而生实有之想的万无一人，怎么能说分明呢？从今世到后世，从后世到今世，在苦世间更相居住，令众生不得出离世间。",
        "【苦谛推习】【义解】这里说生死苦为苦谛。今生死去则后身生出，生死如同昼夜交替，而愚痴的人因为生而感死，频频相续而成苦。这样的因缘，阿难！可知是甚深微妙，从有本生死，明照也微妙。由于生而有死的缘故，所以说因缘。通达今世后世相续累受生死，所以说更苦。明照三世，所以说微妙。这是结苦谛。如果有人问：有老死的因缘吗？问到这个，就回答：有因缘。什么因缘？阿难！老死就答是因为生。死因于生，习（集谛）生有十种，先了知苦，这里是推求集谛。如果有人问：有生的因缘吗？问到这个。有生的因缘，是生有所依存的吗？就回答：有因缘。什么因缘生？有故为生。生因于三有。如果有人问：有「有」的因缘吗？就答有「有」的因缘。什么因缘有？答：受因缘有。因四受而有三有。如果有人问：有受的因缘吗？答：有受的因缘。什么因缘受？答：因为爱求因缘受。",
        "【因缘相生】【义解】这里说由于前身修习八爱，所以中阴有四受，四受既受则有今身。二世显现的缘故，简略而说。通常修习谛理都要究尽十二因缘具备三世，痴人不知今世后世，所以令运心遍及三世；令知轮回、悟四谛，所以说痴人以校计。校计本末，本末作为药，所谓药就是这四谛。阿难！这样从爱求因缘有受，从受因缘有有，从有因缘有生，从生因缘有老死、忧悲、苦、不可意、苦恼生起，这样就具足了最苦的五阴。这五事展转相因，就名为集。了知五事是苦，为苦谛。爱别离苦、住胎苦、生老悲恼真是苦的薮泽。从是有习。这是句倒装，说从集才有这苦。生因缘，阿难！为老死，所以说这是从是导致有是。所以从圣说，从痴致行与德，生而有这老死。",
        "【尽谛无生】【义解】应当从这，阿难！分明为生因缘老死。分明，就是谛实了知集谛。诸处说因缘都是指集谛，将要反推穷尽，所以再推集谛合并。阿难！如果没有生，就没有鱼，也就没有鱼的种子；没有飞鸟，就没有飞鸟的种子；没有蚊虻，就没有蚊虻的种子；没有龙，就没有龙的种子；没有神，就没有神的种子；没有鬼，就没有鬼的种子；没有人，就没有人的种子，各有各的种子。假如证知尽谛无有生，从哪里得五道呢？如果如如有（真如）有，生无有也无，应能令有生。解悟尽谛真如心，则生就无有了，也没有能令生有的。一切时，阿难！无有生的话还有老死不？阿难对佛说：不。无生则无死。这话真实不虚啊！佛便告诉阿难：从这因缘，当知是从是本、从是习、从是因缘，老死是因为生。所以生因缘，阿难！为老死。从这因缘，是从这因缘发起生。解悟无，无生则不老死苦。不了无的人，从四习（集）生就有苦。",
        "【推习重结】【义解】这里四习与止，到爱还和下面有异。从这里以下的结句，都是反复而成。生因缘，阿难！为老死。这是重结。如果有人问：有生的因缘吗？可以答：有生的因缘。什么因缘生？因为有因缘，从这，阿难！因缘，当知令从是有，有因缘生。堕胎三有更有生，十二因缘连属于一世。阿难！如果有因缘无有（三有不存在），难道有鱼和鱼的种子、飞鸟和飞鸟的种子、蚊虻和蚊虻的种子、龙和龙的种子、神和神的种子、鬼和鬼的种子、人和人的种子各各的种子吗？解悟尽谛无有则无五道。如应应有无有，也无有者为有，无有一切。阿难！无有为有生不？阿难说：不。证得真如谛，则便应有无有也再无有。既然以无有作为譬喻，有睹见无有，便令群有一切无有，还会有生吗？反过来问阿难。阿难说没有。所以阿难！从是发、从是本、从是习、从是因缘，生是因为有。",
        "【受因缘有】【义解】有故，从有因缘，阿难！为生。因为作了这四习，所以生以有为根本。如果有人问：有「有」的因缘吗？便说：有什么因缘，阿难！有？可答：为受因缘，有因缘有。这样分明为受因缘有。因四受则有三有。假如阿难！受因缘无有，也无有受有。一切，阿难！无有受为有现不？阿难报：不。无有受缘，也无有受现，当为见。一切无受为有，可见吗？阿难！从是起，从是本、从是习、从是因缘令有受，受因缘，阿难！为有，有因缘，阿难！受。若不达无，便从四习。令有受倒，宜言令受有。有因缘，阿难！受。这样问，对为有。什么因缘有受？可报：爱因缘。从这因缘，阿难！当知为爱因缘受。有因缘阿难受，是句倒装，说有受因缘。八爱心这就是受胎。",
        "【爱因缘受】【义解】阿难！如果没有爱也没有受，也没有当受。一切，阿难！无有爱，为有受不？也有受名不？阿难言：不。解悟无，无爱则无受及当受。又反复反问，是文的常例。阿难！从是发、从是本、从是习、从是因缘为爱因缘受。爱因缘，阿难！为受。阿难！为爱因缘求，求因缘利，利因缘计，计因缘乐欲，乐欲因缘发求以往，爱因缘便不欲捨；由于悭吝而不捨，悭因缘便有家，因为有家因缘便有守护。不解则从是致是。重结。从守行本，阿难！便有刀杖，从有刀杖便有斗诤言语、上下欺侵、若干两舌、多非一致弊恶法。",
        "【守致斗诤】【义解】多非弊法，从守开始生起，是八爱之一。阿难！如果本无有，也无所守，也无有守。一切，阿难！无有守，为有刀杖、斗诤语言、上下欺侵、若干两舌、多非一致弊恶法不？阿难言：不。若解灭，不守于色，宁致若干弊恶不？反问以明理。云无所护，故无所守。下也无二字，重合句耳。阿难！是从、是发、是为本、是为习、是为因缘，刀杖、斗诤语言、上下欺侵、若干两舌、多非一致弊恶法。并守不守二理已现，欲更举四习合为守。从守故，阿难！便有刀杖、斗诤语言、上下欺侵、若干两舌、多非一致弊恶法，如是但为多苦，为从五阴习致。",
        "【家因缘守】【义解】不守者，不了色而守之也。刀杖非一恶，即知大苦，苦谛也。思惟十二因缘，经十二事，一一皆有四谛也。诸习谛推本非一端也，不根十二而止。十六无无漏习尽二慧五耶？推本叱则八爱尽，有四习，以此推之则可知也。又爱为秽海，众恶归焉，何但八耶？言八，举其麁耳。欲界蠢蠢，何互无淫，至乎不还，乃举别耳。家因缘令有守，是故为说是。当从是知，阿难！为家因缘守。由有妻室则有重门击柝之守也。向使栖迟高岸，击柝何施也。故说者，云是上言尔也。若家因缘无有，已无有受，当何因缘有家？一切家因缘无有，宁有家不？宁有刀杖、斗诤语言、上下欺侵、若干两舌、多非一致弊恶法不？阿难言：不。不受此色人，无缘有家。无缘有家，宁有守而惜刀杖大苦集不？",
        "【慳因缘家】【义解】阿难！从是有、从是本、从是习、从是因缘令有守。为守故，从家，阿难！令有守。上从是有者，从家起有守也。以家本习结，因家守成。守因于家，亦颠倒相明也。难捨悭因缘令有家，从是因缘有是。当从是因缘知，阿难？为难捨悭因缘令有家。脑因色欲，思存不捨，由之为家也，故曰是缘有是也。若难捨悭，阿难！无有，亦无有受。已无有受，宁当有慳难捨不？一切，阿难！慳难捨已无有，宁当有家不？阿难白佛言：无有。无有受不捨受也。已无有受，宁当有慳难捨？慳难捨已无有，宁有家不？阿难！从是起、从是本、从是习、从是因缘受家悭难捨故，阿难！令有家。是，是慳惜心也。从往受，阿难！",
        "【发受因缘】【义解】因缘，令有慳难捨，是故有是言，亦从是因缘有是。如是当从是因缘，阿难！可解。为从发受，从是受慳难捨。即彼好仇因之甚惜，故曰往受令有难捨也。是故上说，说从往有是慳也。若阿难！发受无有，宁有受？亦何因缘往受？一切，阿难！无有发受，宁当有慳难捨不？阿难白佛言：不。解无发往，则不有受与至彼也。普不往受，岂慳惜也。本未上。阿难！从是起、从是本、从是习、从是因缘令慳难捨。为发往受故，亦为发有缘故，阿难！令有慳难捨。从发习发遂至不捨也。欲贪因缘，阿难！令有发，是故说是。当从是因缘，阿难！知，为从欲贪因缘令发。淫贪内足则发而适彼也。若欲贪，阿难！无有，已无有因缘，亦何因缘当有欲贪？",
        "【欲贪发往】【义解】一切，阿难！欲贪无有，宁当有发往不？阿难言：不。若行人解淫无有因缘，亦何计当有淫贪耶？普无贪心，何有往受也。凡上云无有，皆明因无有也。一切已下，皆以因及缘无有。阿难！从是发、从是本、从是习、从是因缘令发为有欲贪，故为从欲贪，阿难！令发。令发为有欲贪，句倒也。已发，从发往令有欲贪，是故为说，当从是因缘知，为从发往令有欲贪。此发往计校，欲相造也。《阴持入》曰「愿得往相也」，即第三计也。故说者是，故上说因计生贪也。若无有发往，阿难！亦无有令发往。",
        "【利因缘发】【义解】一切，阿难！虽发往，若有贪欲不？阿难言：不。假解无，无住之因，亦住贪有生不也。阿难！为从是有、从是本、从是习、从是因缘贪欲为有发往因缘令有欲贪。解无如上，若不解则如上为习，于皆结句反复，少发往二字也。从是利故，阿难！令发往，为从是说是。当从是因缘知，为从利因缘令发往。好利甚则思存往也。是上说是，当了利为往缘也。若阿难！以无有利，亦无有求，亦何因缘有求？一切，阿难！已无有利，宁当有发往不？阿难言：不。既解知利，则无有利之求，何当有利求因缘耶？普无有利，岂有发往乎？",
        "【爱因缘求】【义解】阿难！从是有、从是本、从是习、从是因缘发往利故，利故亦发求，从求因故令有利，故说是。从是因缘，当知令从求因缘有利。此八爱或言故说、或云是说，义不异也。以具文于上，此二解之，故云是故首言尔也。若求因缘，阿难！无有，亦何因缘有求？亦从何因缘求？一切，阿难！以无有求，若有见利不？阿难言：不。若求本无所因，亦何得求也。普无求者，利可见不？阿难！从是有、从是本、从是习、从是因缘为有利为有求故，求故，阿难！令有利。或曰发曰生、或曰起、或曰有，义同文别耳。从发故令有求，是故说。当从是知，令从爱求。爱心内无，求之由生。若阿难！无有爱，亦无有求，亦无有因缘，求亦无有爱。",
        "【痛因缘爱】【义解】一切，阿难！爱无有，宁当有求不？阿难言：不。诸因缘唯此一说反上，爱受中即若无有爱，下曰二无有爱耳，余皆在一切上说。因一切下说以因及缘。阿难！从是有、从是本、从是习、从是因缘有爱故令有求，求故令有爱。爱之滋长成乎八也。彼阿难！欲爱亦有爱，是二皆痛相会。此推爱本文终也。欲爱，色爱也。亦有爱，非一也。经曰「心可则为欲」也。是两爱，痛为本、为习、为因缘。从痛发。解如有，则无也。相会，犹相因也。有痛因缘，阿难！若有问是，便言：有。何因缘有？便言：更因缘有。从是因缘，阿难！亦当知令更因缘痛。设问教答也。有六更，故三痛由生也。若阿难！",
        "【更因缘痛】【义解】眼不更，亦无有应当更，眼亦不得更。一切，阿难！眼已不更，宁有眼更不？亦有眼当因缘生不？为乐为苦为亦不乐亦不苦？阿难应：不。若眼知如有不更，眼亦无有。应作眼更者，一复不得此更也。普眼已不更，岂有眼更因缘生三痛不也。阿难！从是有、从是本、从是习、从是因缘令眼更痛。眼更因缘，阿难！令眼知痛。耳亦如是、鼻亦如是、舌亦如是、身亦如是，心不更，阿难！亦无有当更，亦无更因缘令心更。一切，阿难！心无有更，宁当有心更入因缘令有痛不？令有乐不？令有苦不？令有不苦不乐不？阿难应：不。阿难！是为有、是为本、是为习、是为因缘痛令有更，心更因缘，阿难！令有痛。更即有三痛，呼阿难重结，于此颠倒相明结言也。",
        "【名字因缘更】【义解】若有问：有因缘更不？对：为有。何等更有因缘？对：为名字因缘。当从是，阿难！可知令从名字因缘更。更本应是六入，而今是名字六入同出六更，六更同出六情，六情之本则名字，是故想曰名色也。亦应出经时失次也。若从所处有，亦从所处应受，令名身聚有。句倒，云在所处四身，为在所处三有也。将欲说无色，故云受之与有也。有受有有，乃有名色也。阿难！若从所处有，亦从所处应受无有，为有更有名字不？阿难言：不。如有知无受之与有，岂有更而因名字耶？阿难！从所处有，亦从所应受无有，令名身有无有，宁当有对更不？阿难言：不。反复明之。上句云岂有更因名字不？",
        "【识因缘名字】【义解】此句言宁有名字与更对为因也。一切，阿难！名字亦色身无有，为有更不？为从有更不？阿难言：不。此上三反问。于此一问，云普无名色，何从有更乎？天竺言质，无慊其悉也。阿难！为从是发、为从是本、为从是习、为从是因缘、从是是更，令从是名字名字因缘，阿难！令有更。凡上云是因缘是有，次云无，是则无取。后云从发习因缘，即成上句从是有是，故皆如是也。阿难！有名字因缘，设有问，便对为有。何因缘名字？谓识因缘为有。当从是因缘，阿难！解知为识因缘名字。中阴淫识，遂处胎，有五阴。若识，阿难！不下母腹中，当为是名色随精得驻不？阿难言：不。设无中阴淫识，当有猗。精住成名色不？名色已后至有中世也。",
        "【识与名色互缘】【义解】识已前，前世也。三世成十二也。若识，阿难！母腹已下，不得驻去，为有名字得致不？阿难言：不。识，阿难！为本，若男儿、若女儿已坏已亡令无，有为得名字令增长、令所应足不？阿难言：不。纵使中阴乘精入胎，或一二七日而亡，岂有此身耶？或成根男女及命，便堕伤胎，宁得五阴身不乎？自下母胎，则淫识也。一二七日男根女根，已是名字之成。阿难！从是起有，从是本、从是习、从是因缘为名字，从识识因缘，阿难！为有名字。每至结句辄重者，云名色从识注，识为名色因缘，反复言也。有因缘，阿难！识，若问是，便对有。从何因缘有识？名字因缘有识。当从是因缘，阿难！分别解为名字因缘识。",
        "【痴为识本】【义解】惟识之本，本当是行；而今言名字，五大名识也，即六大痴也。有六大痴心作淫行，淫行中有识，共出六大，故名字也。阿难！识不得名字驻已，识不得驻，得增上为有生老死苦、习能致有不？阿难言：不。省文有似上。乘望识入胎受有名字，身或七日或三根成而胎伤，宁滋长成十二缘不也？若当尔者与上不毕也。又此说无名字是无常之说，非尽谛言也。而今少行又文乱，似出经时未皮缺也。就而通之者云：大不信无痴，岂得望行与望识不也。夫万冥存乎痴、万照存乎慧，故此经以痴为本，以谛对也。阿难！从是致。致，生也。从六大生望识也。从是本。",
        "【止诤从慧】【义解】望识以六大为。从是习。习痴以成识也。从是因缘。因痴有识缘也。上二十事实有，十八皆然也。识令有名字，名字因缘有识。十二事穷此。是如是为识因缘名字，名字因缘识，止是说名止是处。对止是诤本现，当从有慧莫受。称名字反复而结之。云止是者，十二事终，是说名字处也。对止是者，上诸云便对也。诤本见者，三耶见也，堕耶见则失正观。正观四慧也，现当见也，故曰诤本见当从慧莫受也。几因缘，阿难！为计痛是为身？阿难言：是法本从佛，是法正本佛，自归本佛，愿令佛说，令从佛说是说，受解利。佛言：听。阿难！善哉善哉！谛受念，佛便说。贤者阿难应：唯然。从佛闻。佛便说是：或，阿难！有见是痛为身。",
        "【三痛计身（一）】【义解】失忧三更而愚堕为身。或有见是痛计非身，但为身更痛法，见是为身。但为已上称痛而云无也。此云身更痛法，与漏分布三痛身更知同也。上三痛亦皆云更知也，以身更为异耳。或一身为是痛，见不为身亦不为痛法，见痛法计是不为身，但为见是身为身。但为已上，亦称上二事云无也。见后解中云不觉，乃后问解三事亦云见也。觉、见，义同耳，但有有为异也。不不解也。觉悟之称也。漏分布曰三痛，心更知，似其事也。若不尔者，宜言三痛觉由身也，上言三痛更由身也，犹六觉六更也。此下散说为三痛病，其文亡而错。得下慧心解三事之重释，以次此，非其事也。彼，阿难！或为在是痛计为身。由痛而修身也。",
        "【三痛非常】【义解】此即下道慧解痛文也，而迸续此为痛病也。当为对说是。此文意称上计痛为身者，辟而执之也。下色重解，不称为宾主也。是痛，贤者！为三辈，有乐痛、有苦痛、有不乐不苦痛。是贤者！三痛见，何痛应作身？乐痛时，阿难！是时二痛已为灭。为苦、亦不乐亦不苦？是时但为乐。更乐痛，阿难！非常，苦要灭。乐，阿难！痛已灭离身，不在身计。将明无身，故云痛有三而身一，何适为身耶？欲言乐痛是身，当其亲乐则无苦与不乐不苦。三痛而今一，乐非身明矣。又令虚诳观其常，身死败灭，以谛照之复非身，明白矣。是如是是时，阿难！苦痛便时，是时为两痛已灭，为乐亦苦，是时但为更苦痛。苦，阿难！痛非常，苦尽法。苦，阿难！",
        "【痛非身见】【义解】痛已尽，身不复更知是时。阿难！与乐痛同义，不别解也。此中乐亦苦，苦上少三字，宜言乐亦不乐不苦也。便字从宜为更也。亦不苦亦不乐，不更是痛，是时两痛灭，痛亦苦。但为是时不苦不乐，更是痛。不苦不乐，阿难！痛法非常，苦尽。不苦不乐，阿难！痛已尽，应无有身，自有是计。或，阿难！为行道。亦同上二义也。长下不字也。中云痛亦苦，宜云乐亦苦也。不大乐不大苦，中中人也。为是非常法，痛为计见身。或有，阿难！为行道。常观三痛计身之见也。放散乐苦痛，为自见计身。如是阿难。因缘不应可为痛作身见身。得明慧观则三痛放散，因缘长息，永无痛之作身想。彼，阿难！或不痛计见是身，但为身法更痛。",
        "【身更痛非身】【义解】但为上称痛而云无也。但云身更痛者，身历三痛而作身也。漏分布曰三痛，身更知，即此事也。便可报：若贤者无有痛更，亦不见所更，宁当应有是不？上更痛计为身，佛教答曰：尚不痛计身，宁犹有身更可修身耶？上痛更称反身更法。身更法，言所更，约耳。言二不见，似尽灭也。设问对，计非身，宁应是法更？是时，阿难！比丘不痛为见计非是身，宁应是法更痛亦见是身不？阿难言：不。既教答无痛，更无缘修身，又反以质阿难也。不痛为见计非是者，言第二身更痛，无第一痛计身也。二与三都无，非常、尽、灭。直言宁应者，此二事皆仍上三痛，故云宁。",
        "【三事俱无身】【义解】宁者，既两痛灭，安得独称身耶？雅理并罗，义不只立也。阿难！是因缘亦不应，亦不可令或一，无有痛计是身，但为身更痛。但为已上亦称也。反称，结句也。彼，阿难！所不计痛为身，亦不见是痛非身。将说第三，云无第一也。亦不身更痛，亦痛法不见不计是身。云无第二也。但为计我，为不觉是身是身。觉，见也。觉三痛计为身也，云不觉觉也。便可报：一切贤者自计身。计独觉也，觉是身也。不更痛。句倒也，即无第二也。宁应有身不？此言自觉身为身，不更痛法。又不痛计身，三名并宁，应独觉身是身耶？",
        "【三痛非身结】【义解】独上三痛，何痛应作身也？当一两灭，何得并称也？是时比丘不痛为身，身亦不更痛，痛法亦不为身有身。二无，第一第二也。但为不觉身耳。如是观身，宁应身不？阿难言：不。云三事并列，何得独有身也。上设问对，此问阿难。如是因缘，阿难！不应令无有痛为身，亦不身为更，亦不应法为身，亦不应不觉身为身。阿难！一切痛为作身已，痛见见是身。事无适作身也。几因缘，阿难！或为行道，不为痛作身，为见不见身！阿难报：是法本从佛，教令亦从佛，愿佛为说，佛说已弟子当受，令是说当为解利。佛告阿难：听是、受是，谛受、重受，念是当为说。如是贤者阿难从佛闻，佛便说是：有，阿难！比丘，不为痛作身，亦不见痛为身。",
        "【行道不痛作身】【义解】行者得四非常，解尽谛慧者，不计三痛而有身也。既不计三痛，则不快痛之见著身想也。亦不为身更，亦不痛法计为身。分痛法耳。宜合痛法。亦上三痛，但身更知、心更知，望得知为异也。亦不见身见为身。见，觉也。上身更、此身觉为异耳。亦不从或有是身，亦不从是见见是身已，如是见不复致世间，令不复受世间。有是身者故，上计痛有是身也。撮三事之二云既无半，则不致受世间也。致，至也。已不复受致世间，便不复忧；已不复忧，便无为度世，便自知为己尽生义，病死忧已毕。三痛身尽则不致不受十一苦也。行已足，所应作已作，不复还在世间。齐是，阿难！或为行道不计痛为身，自方便作，亦不见见为身。齐，至也。",
        "【色行作身（一）】【义解】至此身最后竟身也。身则毕于此，不受更身，故曰不还世间也。几因缘，阿难！或为行道为色作身？阿难报：法本从佛，教令亦从佛，愿佛为说。佛说已，弟子当受令是说，当为解利。佛告阿难：听是、受是，谛受、重受，念是当为说。如是贤者阿难从佛闻，佛便说是：有，阿难！或为行道，为少色行为身。少贪身不乃殷勤。阿难！或为行道，为不少色行为身。将及二，胜一无也。亦色无有量行为身，但为少不色行为身。但为二字宜上在色无量上也。不为少不色，重腾焉也。无量者，殷勤贪内外色也。或有，阿难！为行道，亦不为少色，亦不为无量色。",
        "【色行作身（二）】【义解】腾无第一第二及三也。亦不色少行为身。不色小及第一也。内不少贪、外微著也。或有，阿难！为行道，亦不为少色，亦不为无量色，亦不无有少色行为身。腾无上三。但为不色无量行为身。反第二也。内不色无量，外殷勤也。彼，阿难！或为行道，少色行为身现在。阿难！或为行道，少色行为身，己身坏死，令复见身相像，如是不为是对，行对如是，致亦如是。齐是。现在犹是计贪。少计贪少色以起者，身时虽身死亡，续贪身思存想像，未知系痴，行道不应与此为匹。而愚与俱，以致此身，此而还也。对，匹也、俱也。齐，至也。死而不解无常也。阿难！或为行道，色少行为身，自方便计作。齐是，阿难！或为行道，色少行为身，自方计作。",
        "【色行结使】【义解】齐是，阿难！或为行道，色少行为身令结使。自计方便，方便贪色，命终不绝也。不自坊闲，至此而止，故为身结身使也。上自计方便如当过，下宁也可无一条耳，此说病耳，而云行道道当知也。彼，阿难！或为行道，不少色为作行身，但为色无有量，计作为是身现是。阿难！或为行道，色无有量为计作身，身已坏死，令复现身相像。如是不为是对，行对如是，致亦如是。齐是，阿难！或为行道，为计身色无有量。齐是，阿难！或为行道令色无有量为身令使结。彼，阿难！或为行道，不少色亦无量色计，但为念少色为身现在。",
        "【四种色行结】【义解】阿难！或为行道，不色少为计身，身坏死，令复见身相像。如是不为是对，行对如是，致亦如是。齐是，阿难！或为行道，不色少自计为致身。齐是，阿难！或为行道，不色少令身使结。彼，阿难！或为行道，亦不色少、亦不色无量，亦不无有色少、亦不无有色无量，为堕行身现在。阿难！或为行道，亦不色少、亦不色无量，亦不无有色少、亦不无有色无量，为计堕身，己身坏死，令复见身相像。如是不为是对，行对如是，致亦如是。齐是，阿难！或为行道，不色无量，自计为致身。齐是，阿难！或为行道，令不色为使结。齐是，阿难！或为行道，自计为致身。身几因缘，阿难！为行道，色不行作身？阿难报：是法本从佛，教令亦从佛，愿佛为说。",
        "【不行色作身】【义解】佛说已，弟子当受令是说，当为解利。佛告阿难：听是、受是，谛受、重受，念是当为说。如是贤者阿难从佛闻，佛便说是：或，阿难！为行道，或不为色作身。计四大有身相也都曰也。亦不为色计为身。少色也，脱少字。云解道行者不起小色而滞身也。亦不为色无量。量多著四大，息此多色也。亦不为色少。为下少无字也。无色小，反第一也，亦息此结也。十报内无有小色，外见小端正也。亦不为色无量计为身。为下亦少不字也。此反第二也，行谛亦废之也。十报内不念不趣端正，外见色不趣端正色也。彼，阿难！为行道，不少色为作身，亦不为计是身。如道行道，行谛也。得此慧者，忘少著四大色也。现是，阿难！",
        "【色行不堕身】【义解】为行道，不为少色作身，亦不为堕是身，己身坏死，令不复见是身相像。现是，犹是时也。是行时不贪小色，见身非常灭尽，永绝今身著色之想也。不为是对，行对如是，是无有。齐是。对今身后也。无有身猗之二至，此一也。阿难！为行道，为不少色为身，亦不计为是身。齐是，阿难！为行道，为不少色为身，不使结。云至此无身之相，则无贪身之七使九结也。彼，阿难！或为行道，不为色无量为身，亦不作色为身现在。是，阿难！为行道不色无量为身，亦不计是身，己身坏死，令不复见身相像。不为是对，如是如是，是为无有是。齐是，阿难！为行道不色无量为身，亦不堕身计。如是，阿难！齐是，或为行道，不色无量为身，不使结。彼，阿难！",
        "【四不行色结】【义解】或为行道，不为不色少为身，亦不堕身计。现是，阿难！为行道，不色少为身，亦不堕身计，己身坏死，令不复见身相像。不为是对，如是如是，是为无有是。齐是，阿难！为行道，不为不色少为身，亦不堕身计。如是，阿难！齐是为行道，不为不色少，令不使结。彼，阿难！或为行道，不行不色无量为身，亦不堕计是身。现是，阿难！为行道，不为不色，阿难！为身，亦不堕计为成身，己身坏死，如是身令不复见是计。不为是对，如是如是，是为无有是。齐是，阿难！为行道，不行不色无量为身，亦不堕计是身。齐是，阿难！为行道，不行不色无量，亦令不使结。",
        "【七识止处】【义解】齐是，阿难！或为行道，不行不色无量为身，亦不成身，亦不堕计是身。亦有是七处，阿难！令识得驻，亦有二受行从得解。三道则张欲界为五，并三界天为一，九神止处，则分色无色，合欲为一也。论五道者，以流浪受苦为失，故精说三恶道，总天为一也。说九止者，论能弘教受三观者，故自人始，不及三苦也。分一受者精粗相，从观法不异也。二受皆居满毕之位，故有解名也。有色为令从是有若干身、若干思想辟，或人或天，是为第一识止处。有色为令从是一身，若干思想辟天，名为梵天长寿本在处，是为第二识止处。有色为令从是一身，若干思想辟天，名为明声，是为第三识止处。有色为令从是一身一像思，亦一辟天，名为遍净，是为第四识止处。",
        "【二受行解脱】【义解】有不色为令从是一切从色想度多想灭，为无量空，空慧受意止辟天，名为空慧行，是名第五识止处。有不色为令从是一切从空行竟，过无量识，从慧受意止辟天，名为识慧，是名为第六识止处。有不色为令从是一切从识慧过度无量，不用从是慧意受止辟天，名为不用从受慧，是为第七识止处。何等为，阿难！亦有二受行？从得解有，从色因缘行道，令不更思想辟天，名为不思想，是为一受行。从得解有，从不色因缘行道，一切从不用得度，为受不思想亦有思想受行止辟天，名为不思想亦有思想。是为二受行。从得解彼，阿难！所第一识止处，为从色行因缘行道，若干身、若干思想辟，名为人，亦一处。色，身也、有也，有欲之形，故曰色也。",
        "【观第一识处】【义解】由欲界身行道谛，故曰行道也。六天已下其形非一，故曰若干也。心亦各异，故曰若干想也。辟，行字也。若阿难！行道，是识止处已知。知欲天及人，阴持入身为本也。亦知是识从是习。习天及人，识不能舍也。知者，慧也。亦知从是没。没，尽也。从天及人身天下灭者，谛知如篾曰尽也。亦知是所乐。七处结曰昧也。贪乐天及人身，故曰乐也。知之为尽。亦知是更苦。天及人身由之受苦也。知一苦则慧也。亦知是从得出要，如有知。出要法句，言得要，生尽也。故七处曰欲，能治、能弃、能度也。尽谛有四事，出要是其一也。凡六事皆曰知，行道谛之慧也。六事皆曰是，是六天已下下及人身，识所依也。",
        "【三观七处义】【义解】《七处三观经》一皆知五阴之一。而阴有六情也，一一皆知阴。阴有习三四，知阴尽行道。又曰：亦知色味、亦知色出要。此七处也。三观者，观身色、观五阴、观六情也。三观即七处之每第一阴入也。言以道谛、尽谛、苦出要谛，观阴人及乐而阴之也。五阴覆盖，经以五阴为五习。尽为七处昧，苦出要为三观。文小异大同。身三经，唯《七处三观经》有道谛，二经皆七事而已。然俱曰行道亦道谛也，皆曰知亦谛也，如至识知。或曰如本知，知非谛。何也？知观同义也。九九止即天身为观地，习天之习，天之身会灭，行道味乐天乐。天乐，乐必有苦，能断天贪，可名活道，故曰出要也。皆四谛观观九处也，所谓微而显、约而具也。十报单用阴习尽而止也。",
        "【观二至四识处】【义解】是时阿难！为行道所识止处，可应求、可应望、可应住处？阿难言：不。若行道慧，以四谛观观人身，宁有贪求望想此住止处不？答曰无也。彼，阿难！第二识止处，为从色行因缘行道，若干身一想辟天，名为梵身长寿本第一在处。始行一禅生四梵，名梵、小梵、无量大梵、梵辅。身不相类，故曰若干身，犹此人之优劣也。心未纯一，故曰非一想也。若阿难！行道，是识止处以知，亦是识止处，从是习、亦知从是没、亦知是所乐、亦知是更苦、亦知是从得出要如有知。是时，阿难！为行道所识止处，可应求、可应望、可应住处？阿难对言：不。彼，阿难！第三识止处，为从色行因缘行道，一身若干想辟天，名为明。",
        "【观五至七识处】【义解】若阿难！为行道是识止处已知，亦是识止处从是习、亦知从是没、亦知是所乐、亦知是更苦、亦知是从要得出如有知。是时，阿难！为行道所识止处，可应求、可应望、可应住处？阿难对言：不。进行二禅。以知养恬阴乎念持，生此四明天，身表光相、混然大齐，心犹不一，故曰若干也。彼，阿难！第四识止处，为从色行因缘行道，一像身一思想辟天，名为遍净。若阿难！为行道是识止处己知，亦是识止处从是习、亦知从是没、亦知是所乐、亦知是更苦、亦知从是要得出如有知。是时，阿难！为行道所识止处，可应求、可应望、可应住处？阿难对言：不。此是第三天也。宜言净天天也，容表晖炎四天。若一其心，恬豫恒游禅思，故曰一。彼，阿难！第五识止处，为从不色行因缘行道，一切从色得度，地想已没，无量空空慧行受止辟天，名为空慧。若阿难！为行道是识止处已知，亦是识止处从是习、亦知从是没、亦知是所乐、亦知是更苦、亦知从是要得出如有知。是时，阿难！为行道所识止处，可应求、可应望、可应住处？阿难对言：不。地者，恚灭，心如地也。想已没，断求也，无量空也。彼，阿难！第六识止处，为从不色行因缘行道，一切从空慧度识无量受慧行止辟天，名为识慧。若阿难！为行道，是识止处已知，亦是识止处从是习、亦知从是没、亦知是所乐、亦知是更苦、亦知从是要得出如有知。",
        "【观二受行处】【义解】是时，阿难！为行道所识止处，可应求、可应望、可应住处？阿难对言：不。空识定者，观对识空，不本来也。彼，阿难！第七识止处，为从不色行因缘行道，一切从识慧度，无量不用，已捨受慧行辟天，名为不用受慧行。若阿难！为行道，是识止处已知，亦是识止处从是习、亦知从是没、亦知是所乐、亦知是更苦、亦知从是要得出如有知。是时阿难！为行道所识止处，可应求、可应望、可应住处？阿难对言：不。色恚求生，生而即遣，不俟终日观而后知也，不用观也。彼，阿难！第一受行从得解有，从色因缘行道无有想，亦不受辟天，名不思。若阿难！为行道，己知是从受、亦知从受习、亦知从是没、亦知是所乐、亦知是更苦亦知从是要得出如有知。",
        "【八解脱处】【义解】是时阿难！为行道，是受行从得解，可应求、可应望、可应住处？阿难对言：不。不思无结爱天也，四阿那含之第四天也。四阿那含爱，身生第四禅。六增之第二已上四天，此无漏第四禅局也。四禅之第六天名爱胜，是无思天，共在一天上耳。彼，阿难！第二受行从得解，有从不色因缘行道，一切不用从慧得度，过无有思想亦未离思想为受行止。正受定也。辟天名为无有思想解。若阿难！为行道，是受行从得解，已知为是解从是习、亦知从是没、亦知是所乐、亦知是更苦、亦知从是要得出如有知。是时，阿难！为行道，是受行从得解，可应求、可应望、可应住处？阿难对言：不。无想者，知空而制想不令起也。",
        "【慧得解脱】【义解】此上八止皆如，应知此八处，亦知八处习、亦知八处尽、亦知八处乐、亦知八处苦、亦知八处要得出，义同故不二训之也。若，阿难！为行道，如是知、如是见，说为不知不见。若有是结使，是时应说为常，是时应说非常。婆罗门云断灭见常也。是时应说世间有本，是时应说世间无有本。本，要也。有要、无要耳。是时应说道以死复生，是时应说道不得死。或见七反生死者，故曰死复生。或至尼先天者，故曰不死也。为有无有。或曰有度世，或曰无度世。度世死，从是结使。是时阿难！为行道，是七识止处，二受行从得解。如是如有从谛慧见。从是意已解、已得解脱，是名为，阿难！为行道无所著、从慧得解脱。",
        "【八解脱释义】【义解】反称得道不得死。是五耶结使，经乎九止，行者以四谛观之，长得息解，成阿罗汉也。亦有，阿难！八解脱处。何等为八？色观色，是为第一解脱处。内外身著观两事也。内观色，不想外观色，是为第二解脱处。遍著外身也。观三十六物，净身受观行止，是为第三解脱处。遍著己身，则三十六物观也。从第一禅至四禅，皆三观也。人病不同，或贪己身、或贪外色、内外俱贪，故有三观也。四意止观亦复如是，单举禅要则三观也，耳其转除，则四禅也。一切从色想已度。已过四禅色天，次及空也。灭地想。灭恚心如土尘，故曰如地也。若干想不念，无量空慧已受竟辟天，名为空慧，是名为第四解脱处。四空定文同，故不一一解也。",
        "【灭尽定义】【义解】一切从空慧，已度无量识慧受竟辟天，名为识慧，是名为第五解脱处。一切从识慧得度，无所有，不用受慧竟行辟天，名为不用无所用慧行，是为第六解脱处。一切从不用慧得度，无有思想亦不无有思想竟受止辟天，名为思想，是名为第七解脱处。一切从无有思想竟得度。将已竟四空，次及灭定也。灭思想亦觉尽身已更竟受止，是为第八解脱处。心之流放眴息生灭之间，抚宇宙之表矣。身之所复，无不待行。行慈定者，灭心想身知，屈如根株、冥如死灰，雷霆不能骇其念、山燋不能伤其虑，萧然与大虚齐量、恬然与造化俱游，曰灭定也。",
        "【总结流通】【义解】若已，阿难！行道，七识止处、二受行从得解脱，亦是八解脱处是。如有是慧已，更见从是戢却不用，已得解脱，如是本福，己身更竟止，是名，阿难！行道无所著，从两行得解脱。佛说如是，阿难受行。"
    ]
    for i, m in enumerate(moderns):
        trans_list[i]["modern"] = m
    with open(out, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    print(f"t1693 done, {len(moderns)} paragraphs")

